local KTool = CS.Engine.Lib.KTool
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local cs_coroutine = import("XLua.cs_coroutine")
local Yielders          = CS.Engine.Lib.Yielders
local SDKService = import('Game.Entry.SDKService')

--- from: Assets/BundleResources/Prefabs/Store/ContinuousRechargeDialog.prefab
---@class ContinuousRechargeCell
---@field Env                           	ContinuousRechargeCell
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field EffectRoot                    	UnityEngine.RectTransform
---@field GoodNode3                     	Engine.Modules.LuaBehaviour
