---@field OriginalPrice                 	TMPro.TextMeshProUGUI
---@field NowPrice                      	TMPro.TextMeshProUGUI
---@field Arrow                         	UnityEngine.RectTransform
---@field LeftTime                      	UnityEngine.UI.Text
---@field BtnBuy                        	UnityEngine.UI.Button
