local ContinuousRechargeCell = Class('ContinuousRechargeCell')
function ContinuousRechargeCell:__init()
    
    self.vos = nil
    self.index = nil
    self.curState = nil
end

function ContinuousRechargeCell:__delete()
    
    self.vos = nil
    self.index = nil
    self.serverData = nil
end

function ContinuousRechargeCell:Awake()
    SetButtonAction(self.BtnBuy.gameObject,function() self:OnPayBtnClick() end)
    self:InitComponent()
end

function ContinuousRechargeCell:InitComponent()
    KTool.SetActive(self.NotOpenNumber.gameObject,false)
    KTool.SetActive(self.ImgLine.gameObject,false)
    KTool.SetActive(self.Open.gameObject,false)
end

---这里的Vo是一个数组  里面有2份Vo 一个是原价的 一个是折扣价的  回调是重新请求服务器数据
function ContinuousRechargeCell:RefreshUI(vos,serverData,index,callBack)
    ---要根据服务器的Id 来决定使用那个礼包的数据
    self.vos = vos
    self.serverData = serverData
    self.index = index
    local data = self.serverData.product

    if  not isNull(data) then
        ---根据服务器发过来的组别来判断当前是那一个组在售卖 大于的说明没解锁  小于的说明已经买过了
        if self.index < data.group then
            KTool.SetActive(self.SellOut.gameObject,true)
            KTool.SetActive(self.SoonOpen.gameObject,false)
            KTool.SetActive(self.Close.gameObject,false)
            KTool.SetActive(self.HasOpened.gameObject,false)
            KTool.SetActive(self.EffectRoot.gameObject,false)
            KTool.SetActive(self.Open.gameObject,false)
            KTool.SetActive(self.NotOpenNumber.gameObject,true)
            self.ImgNumber.Status = index
        elseif self.index == data.group then
            ---说明这个组是当前正在售卖的组
            KTool.SetActive(self.SellOut.gameObject,false)
            KTool.SetActive(self.Close.gameObject,false)
            KTool.SetActive(self.NotOpenNumber.gameObject,false)
            KTool.SetActive(self.EffectRoot.gameObject,true)
            local vo = self:GetVoById(data.productId)
            ---说明当前组还没有解锁
            if self.serverData.unlockProductTimeLeft > 0 then
                KTool.SetActive(self.SoonOpen.gameObject,true)
                KTool.SetActive(self.HasOpened.gameObject,false)
                KTool.SetActive(self.NotOpenNumber.gameObject,true)
                self.ImgNumber.Status = index
                self:StartOpenTimeCountDown(self.serverData.unlockProductTimeLeft,callBack)
            elseif self.serverData.productCountdownTimeLeft > 0 then
                KTool.SetActive(self.SoonOpen.gameObject,false)
                KTool.SetActive(self.HasOpened.gameObject,true)
                KTool.SetActive(self.Open.gameObject,true)
                KTool.SetActive(self.NowPriceRoot.gameObject,true)
                KTool.SetActive(self.CountDown.gameObject,true)
                KTool.SetActive(self.ImgLine.gameObject,true)
                CfUtils.FillText(self.OriginalPrice, CfUtils.GetDisplayPrice(vo.oldPrice))
                CfUtils.FillText(self.NowPrice, CfUtils.GetDisplayPrice(data.price , data.channelProductId) )
                self:StartLeftTimeCountDown(self.serverData.productCountdownTimeLeft,callBack)
            else
                KTool.SetActive(self.SoonOpen.gameObject,false)
                KTool.SetActive(self.HasOpened.gameObject,true)
                KTool.SetActive(self.Open.gameObject,true)
                KTool.SetActive(self.NowPriceRoot.gameObject,false)
                KTool.SetActive(self.CountDown.gameObject,false)
                CfUtils.FillText(self.OriginalPrice, CfUtils.GetDisplayPrice(data.price , data.channelProductId) )
            end
        else
            --- 大于的说明没解锁
            KTool.SetActive(self.NotOpenNumber.gameObject,true)
            self.ImgNumber.Status = index
            KTool.SetActive(self.Open.gameObject,false)
            KTool.SetActive(self.SellOut.gameObject,false)
            KTool.SetActive(self.SoonOpen.gameObject,false)
            KTool.SetActive(self.Close.gameObject,true)
            KTool.SetActive(self.HasOpened.gameObject,false)
            KTool.SetActive(self.EffectRoot.gameObject,false)
        end
    else
        ---当Data为空的时候  这时认为所有的都买了
        KTool.SetActive(self.SellOut.gameObject,true)
        KTool.SetActive(self.SoonOpen.gameObject,false)
        KTool.SetActive(self.Close.gameObject,false)
        KTool.SetActive(self.HasOpened.gameObject,false)
        KTool.SetActive(self.EffectRoot.gameObject,false)
        KTool.SetActive(self.Open.gameObject,false)
        KTool.SetActive(self.NotOpenNumber.gameObject,true)
        self.ImgNumber.Status = index
    end
    ---只有第三个Cell 不显示 箭头
    KTool.SetActive(self.Arrow.gameObject,(self.index ~= 3))
    self.ImgIcon.Status = index
    ---不管什么情况 不影响奖励展示
    local vo = self.vos[1]
    self:SetGoodNodeShow(vo)
end

function ContinuousRechargeCell:StartLeftTimeCountDown(time,callBack)
    self:RecycleTimer(self.leftTimer)
    self.LeftTime.text = CfUtils.GetTimeHMS(checkNumber(time))
    self.leftTimer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if count > 0 then
            self.LeftTime.text = CfUtils.GetTimeHMS(checkNumber(count))
        else
            CDTimerModule.GetInstance():RemoveCD(self.leftTimer)
            self.leftTimer = nil
            ---播放完动画后  再执行回调
            cs_coroutine.start(function()
                self.AnimRoot:Play("ContinuousRechargeDialogGiftbagOpen")
                coroutine.yield(Yielders.GetWaitForSeconds(0.67))
                if  callBack then
                    callBack()
                end
            end)
        end
    end, time, false, true)
end

function ContinuousRechargeCell:StartOpenTimeCountDown(time,callBack)
    self:RecycleTimer(self.openTimer)
    self.OpenCountDown.text = CfUtils.GetTimeHMS(checkNumber(time))
    self.openTimer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if count > 0 then
            self.OpenCountDown.text = CfUtils.GetTimeHMS(checkNumber(count))
        else
            CDTimerModule.GetInstance():RemoveCD(self.openTimer)
            self.openTimer = nil
            cs_coroutine.start(function()
                self.AnimRoot:Play("ContinuousRechargeDialogGiftbagSwitch")
                coroutine.yield(Yielders.GetWaitForSeconds(0.65))
                if  callBack then
                    callBack()
                end
            end)
        end
    end, time, false, true)
end

function ContinuousRechargeCell:GetVoById(id)
    for i, v in pairs(self.vos) do
        if id == v.id then
            return v
        end
    end
    return nil
end

---设置展示奖励
function ContinuousRechargeCell:SetGoodNodeShow(vo)
    for i = 1, 3 do
        local goodItem = self["GoodNode"..i]
        if goodItem then
            if vo.showData[i] then
                KTool.SetActive(goodItem.gameObject,true)
                --local scale = (i == 1 and 0.6 or 0.48)
                CfUtils.RefeshGoodGo2(goodItem,vo.showData[i].goodsId, vo.showData[i].goodsNum, nil, nil, function()
                end)
            else
                KTool.SetActive(goodItem.gameObject,false)
            end
        end
    end
end

function ContinuousRechargeCell:RecycleTimer(timer)
    if not timer then return end
    CDTimerModule.GetInstance():RemoveCD(timer)
    timer = nil
end

function ContinuousRechargeCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:RecycleTimer(self.leftTimer)
    self:RecycleTimer(self.openTimer)
    self:Delete()
end

function ContinuousRechargeCell:OnPayBtnClick()
    if not isNull(self.serverData) and next(self.serverData) then
        if self.serverData.product.group == self.index then
            SDKService:GetInstance():PayMoney({
                productId = self.serverData.product.productId,
                channelProductId = self.serverData.product.channelProductId,
                productDesc = localize("连续充值"),
                payAmount = self.serverData.product.price,
                data = self.serverData.product
            })
        end
    end
end

return ContinuousRechargeCell